+      x: 0.75,
+      y: 2.65,
+      w: 8.5,
+      h: 0.75,
+      fontFace: FONTS.body,
+      fontSize: 16,
+      color: theme.secondary
+    }
+  );
+
+  // Landscape framing (no new stats beyond brief)
