+    [
+      { text: "Competitive landscape (April 2026):\n", options: { bold: true } },
+      {
+        text:
+          "Frontier proprietary labs co-lead on intelligence, while open-weight models lead on throughput and cost — implying deliberate trade-offs rather than a single dominant choice."
+      }
+    ],
