+      x: 0.95,
+      y: 3.82,
+      w: 8.1,
+      h: 0.95,
+      fontFace: FONTS.body,
+      fontSize: 14,
+      color: theme.primary
+    }
+  );
+
+  // Source stamp
+  slide.addText("Source: Artificial Analysis (captured Apr 10, 2026)", {
+    x: 0.75,
