+const { THEME, FONTS, addTopBar, addFooter, addCard } = require("./theme");
+
+const slideConfig = {
+  type: "content",
+  index: 2,
+  title: "Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57"
+};
+
+const RANKING = [
+  { rank: 1, model: "Gemini 3.1 Pro Preview", provider: "Google", score: 57 },
+  { rank: 2, model: "GPT-5.4 (xhigh)", provider: "OpenAI", score: 57 },
+  { rank: 3, model: "Claude Opus 4.6 (max)", provider: "Anthropic", score: 53 },
+  { rank: 4, model: "Muse Spark", provider: "Meta", score: 52 },
+  { rank: 5, model: "Claude Sonnet 4.6 (max)", provider: "Anthropic", score: 52 },
+  { rank: 6, model: "GLM-5.1", provider: "Z AI", score: 51 },
+  { rank: 7, model: "Grok 4.20 0309 v2", provider: "xAI", score: 49 },
+  { rank: 8, model: "Gemini 3 Flash", provider: "Google", score: 46 },
+  { rank: 9, model: "DeepSeek V3.2", provider: "DeepSeek", score: 42 },
+  { rank: 10, model: "NVIDIA Nemotron 3 Super", provider: "NVIDIA", score: 36 },
+  { rank: 11, model: "gpt-oss-120B (high)", provider: "OpenAI", score: 33 }
+];
+
+function createSlide(pres, theme = THEME) {
+  const slide = pres.addSlide();
+  addTopBar(slide, theme, slideConfig.title, "Artificial Analysis Intelligence Index (composite benchmark score)");
+
+  // Left: full table
+  const tableX = 0.55;
+  const tableY = 1.55;
+  const tableW = 5.9;
+  const tableH = 3.6;
+  addCard(slide, theme, tableX, tableY, tableW, tableH);
+
+  slide.addText("Full 11-model ranking", {
+    x: tableX + 0.2,
+    y: tableY + 0.15,
+    w: tableW - 0.4,
+    h: 0.35,
+    fontFace: FONTS.header,
+    fontSize: 14,
+    bold: true,
+    color: theme.primary
+  });
+
+  const headerY = tableY + 0.55;
+  slide.addShape("rect", {
+    x: tableX + 0.2,
+    y: headerY,
+    w: tableW - 0.4,
+    h: 0.32,
+    fill: { color: theme.primary, transparency: 8 },
+    line: { color: theme.primary, transparency: 40 }
+  });
+  const cols = {
+    rank: { x: tableX + 0.25, w: 0.55, label: "Rank" },
+    model: { x: tableX + 0.85, w: 2.95, label: "Model" },
+    provider: { x: tableX + 3.85, w: 1.25, label: "Provider" },
+    score: { x: tableX + 5.15, w: 1.05, label: "Index" }
+  };
+
+  for (const key of Object.keys(cols)) {
+    const c = cols[key];
+    slide.addText(c.label, {
+      x: c.x,
+      y: headerY + 0.05,
+      w: c.w,
+      h: 0.25,
+      fontFace: FONTS.body,
+      fontSize: 10,
+      color: theme.bg
+    });
+  }
+
+  const rowStartY = headerY + 0.36;
+  const rowH = 0.265;
+  RANKING.forEach((r, i) => {
+    const y = rowStartY + i * rowH;
+    const isTop = r.score === 57;
+    if (i % 2 === 0) {
+      slide.addShape("rect", {
+        x: tableX + 0.2,
+        y,
+        w: tableW - 0.4,
+        h: rowH,
+        fill: { color: theme.bg, transparency: 0 },
+        line: { color: theme.bg, transparency: 100 }
+      });
+    }
+
+    if (isTop) {
+      slide.addShape("rect", {
+        x: tableX + 0.2,
+        y,
+        w: tableW - 0.4,
+        h: rowH,
+        fill: { color: theme.light, transparency: 35 },
+        line: { color: theme.light, transparency: 65 }
+      });
+    }
+
+    slide.addText(String(r.rank), {
+      x: cols.rank.x,
+      y: y + 0.03,
+      w: cols.rank.w,
+      h: rowH,
+      fontFace: FONTS.body,
+      fontSize: 10,
+      color: theme.secondary
+    });
+    slide.addText(r.model, {
+      x: cols.model.x,
+      y: y + 0.03,
+      w: cols.model.w,
+      h: rowH,
+      fontFace: FONTS.body,
+      fontSize: 10,
+      color: theme.primary
+    });
+    slide.addText(r.provider, {
+      x: cols.provider.x,
+      y: y + 0.03,
+      w: cols.provider.w,
+      h: rowH,
+      fontFace: FONTS.body,
+      fontSize: 10,
+      color: theme.secondary
+    });
+    slide.addText(String(r.score), {
+      x: cols.score.x,
+      y: y + 0.03,
+      w: cols.score.w,
+      h: rowH,
+      fontFace: FONTS.body,
+      fontSize: 10,
+      color: theme.primary,
+      align: "right"
+    });
+  });
+
+  // Right: key callouts
+  const rightX = 6.65;
+  const rightY = 1.55;
+  const rightW = 2.8;
+  const rightH = 3.6;
+  addCard(slide, theme, rightX, rightY, rightW, rightH);
+
+  slide.addText("What to notice", {
+    x: rightX + 0.2,
+    y: rightY + 0.15,
+    w: rightW - 0.4,
+    h: 0.35,
+    fontFace: FONTS.header,
+    fontSize: 14,
+    bold: true,
+    color: theme.primary
+  });
+
+  slide.addText(
+    [
+      { text: "• Two-way tie at 57 (Google + OpenAI)\n" },
+      { text: "• 57 → 33 spread across the leaderboard\n" },
+      { text: "• Open-weight models sit mid-tier (gap narrowing)", options: {} }
+    ],
+    {
+      x: rightX + 0.25,
+      y: rightY + 0.65,
+      w: rightW - 0.5,
+      h: 1.3,
+      fontFace: FONTS.body,
+      fontSize: 12,
+      color: theme.secondary
+    }
+  );
+
+  // Optional supporting image from brief
+  slide.addImage({
+    path: "./imgs/chart_intelligence_index_ranking.jpg",
+    x: rightX + 0.2,
+    y: rightY + 2.05,
+    w: rightW - 0.4,
+    h: 1.35
+  });
+
+  slide.addText("Figure: Intelligence Index ranking (Artificial Analysis)", {
+    x: rightX + 0.2,
+    y: rightY + 3.43,
+    w: rightW - 0.4,
+    h: 0.25,
+    fontFace: FONTS.body,
+    fontSize: 8,
+    color: theme.secondary
+  });
+
+  addFooter(slide, theme, 2);
+  return slide;
+}
+
+if (require.main === module) {
+  const pptxgen = require("pptxgenjs");
+  const pres = new pptxgen();
+  pres.layout = "LAYOUT_16x9";
+  createSlide(pres, THEME);
+  pres.writeFile({ fileName: "slide-02-preview.pptx" });
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
PATCH

